$a = random(2,9,1); $ans1 = Compute("1")->with( tolType => 'absolute', tolerance => .000000000000000000001, ); $ans2 = Compute("0")->with( tolType => 'absolute', tolerance => .000000000000000000001, ); $ans3 = Compute("-pi/2")->with( tolType => 'absolute', tolerance => .000000000000000000001, ); $ans4 = Compute("3pi/2")->with( tolType => 'absolute', tolerance => .000000000000000000001, ); $ans5 = str_cmp("none");
